		bodyBuilder.part("file", fileContent).filename("orig");
		bodyBuilder.part("json", json, MediaType.APPLICATION_JSON);

		testClient.post().uri("/multipartfile")
				.bodyValue(bodyBuilder.build())
				.exchange()
